fn new_gss_node (& mut self , nonterminal_id : NonterminalId , input_index : u32) -> GssNodeId { let gss_node_id = GssNodeId (self . gss_nodes . len () as u32) ; let gss_node = GSSNode :: new (gss_node_id , nonterminal_id , input_index) ; record ! (self , GSSNodeCreated , nonterminal_id , input_index) ; self . gss_nodes . push (gss_node) ; gss_node_id }
