fn parse_error (& self) -> Option < & ParseError > { self . parse_errors . first () }
fn add_parse_error (& mut self , input_index : u32 , slot_id : SlotId , gss_node_id : Option < GssNodeId > , kind : impl FnOnce () -> ParseErrorKind ,) { let level = self . parse_errors . first () . map_or (0 , | e | e . input_index) ; if input_index < level { record ! (self , ParseError , input_index , slot_id , gss_node_id , kind ()) ; return ; } let kind = kind () ; record ! (self , ParseError , input_index , slot_id , gss_node_id , kind . clone ()) ; if input_index > level { self . parse_errors . clear () ; } self . parse_errors . push (ParseError { input_index , slot_id , gss_node_id , kind , }) ; }
